INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('A038-03','R038-03','CN0134','acceptance2022','screening',2,'分质回用及减量','贵金属沉降回收后测溶剂与盐，比较高盐独立蒸发和低盐UF/RO回用；不可依据低投资推吨水成本','conditional','现场水量、水质、浓水合法出路、费用和运行条件须核实','原D012-02同范围修订；2022验收，站能力与总口监测明确，图4-2截图超时，具体单元仍待核','INFERRED候选非实装','现行污水工艺/站负荷、金属/盐分、膜及费用','分股采样、盐水衡算、膜小试及运行费用比较','保持及优化已有处理、回收和合法纳管',NULL,NULL,NULL,NULL,NULL,NULL,'缺实际六维证据，不赋分','2026-11-28');
